typedef unsigned long long big_int;
extern "C" unsigned int strlen(const char *);
#define assert(x) ((void)0)

class stringx;
class string_buf
{
protected:
    friend class stringx;
    big_int *data;
    int ref_count;
    int char_length;
    int block_length;
    int max_blocks;
public:
    void set_to_cstr(const char *str, int len = -1);
};

class stringx
{
protected:
    static string_buf *find_empty_buffer(int capacity, const char *str_just_for_error_msgs);
    static string_buf *find_cached_string(const char *str, int len = -1);
    static void add_buf_to_cache(string_buf *buf);
    static string_buf *acquire_buffer(const char *str, int len = -1);
};

string_buf *stringx::acquire_buffer(const char *str, int len)
{
	string_buf *buf;

	buf = find_cached_string(str);
	if (buf == NULL) {
#ifdef STRINGX_DEBUG
		cache_misses++;
#endif
		if (len == -1)
			len = strlen(str);
		buf = find_empty_buffer(len, str);
		assert(buf);
		buf->set_to_cstr(str, len);
		add_buf_to_cache(buf);
	} else {
#ifdef STRINGX_DEBUG
		cache_hits++;
#endif
	}

	return buf;
}
